-- 事故通知到人（2026-11-25，ADR-0037；契约 plans/incident-notification-accept.md）。
-- 设计约束：
--   ① 通知是**派生数据**：只带定位信息（事故 ID / 标题 / 优先级 / 时限 / 事件类型），
--      不复制 query、诊断正文、评论正文或引用片段；事实来源仍是 incidents 与审计。
--   ② 按收件人持久化隔离：所有读写都带 tenant + recipient，tenant/recipient 只来自 JWT。
--   ③ 去重靠唯一键 (tenant, recipient, dedupe_key)：冲突不是错误，是同一事件的重放。
--   ④ 通知行与事故变更同一事务写入；外发在提交后异步进行，失败不回滚。
-- 自增主键写 IDENTITY 而不是 AUTO_INCREMENT：H2 的 PostgreSQL 兼容模式（测试库）不认
-- AUTO_INCREMENT，而 GENERATED BY DEFAULT AS IDENTITY 在 H2 两种模式与 PostgreSQL 10+ 都成立。
CREATE TABLE IF NOT EXISTS incident_notifications (
    notification_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tenant          VARCHAR(64)   NOT NULL,
    recipient       VARCHAR(64)   NOT NULL,
    incident_id     VARCHAR(64)   NOT NULL,
    kind            VARCHAR(32)   NOT NULL,
    title           VARCHAR(120)  NOT NULL,
    priority        VARCHAR(8)    NOT NULL DEFAULT '',
    due_at          TIMESTAMP     NULL,
    dedupe_key      VARCHAR(160)  NOT NULL,
    created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    read_at         TIMESTAMP     NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_incident_notifications_recipient_dedupe
    ON incident_notifications(tenant, recipient, dedupe_key);
CREATE INDEX IF NOT EXISTS idx_incident_notifications_recipient_unread
    ON incident_notifications(tenant, recipient, read_at, created_at);
